import test from 'node:test';
import assert from 'node:assert/strict';
import { randomUUID, createHash, createHmac } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { DomainStore, DOMAIN_POLICY, canonicalJSON } from './domain_store.mjs';
import { DOMAIN_SCHEMA_SQL } from './domain_schema.mjs';
const start=Date.parse('2026-10-05T00:00:00.000Z');
const schema={version:1,fields:{title:{type:'string',required:true},note:{type:'string',nullable:true},amount:{type:'number'},currency:{type:'string'},status:{type:'string',enum:['open','done','cancelled']},links:{type:'array'},planner:{type:'object'},organizer:{type:'object'}},groups:{money:['amount','currency']},statusFields:['status'],referenceFields:['links'],processors:{planner:['planner'],organizer:['organizer']},dedupFields:['title'],immediateDeleteSources:['immediate']};
const all=['read','create','patch','status','ack','delete','restore','merge','purge'];
function fixture(t,{file=false,verification=true,mode='authoritative'}={}){
 const dir=file?mkdtempSync(path.join(tmpdir(),'i-domain-synthetic-')):null;const name=file?path.join(dir,'fixture.sqlite'):':memory:';let db=new DatabaseSync(name);db.exec("CREATE TABLE core_metadata(key TEXT PRIMARY KEY,value TEXT);INSERT INTO core_metadata VALUES('schema_version','6'),('node_id','core-test'),('cursor_secret','synthetic-secret-only');");db.exec(DOMAIN_SCHEMA_SQL);let now=start;const options={nodeId:'core-test',cursorSecret:'synthetic-secret-only',clock:()=>now,verifyAuthorization:verification?({request,authorizationRef,targets})=>authorizationRef==='bound:'+request.op_id&&targets.every(x=>x.id):null};let store=new DomainStore(db,options);store.registerDomain('example',schema,{mode});
 const principal=(id='agent',extra={})=>{const issued=store.configurePrincipal({principal_id:id,device_id:'device-'+id,installation_id:'install-'+id,scopes:all.map(a=>'example:'+a),actors:id==='user'?['user_direct','user_via_agent']:['agent_inferred','import'],trusted_interactive:id==='user',import_sources:['fixture'],...extra});return {p:store.authenticate(issued.token),...issued};};
 const a=principal(),u=principal('user');const intent=(kind='create',overrides={})=>{const op={domain_protocol_version:1,core_instance_id:'core-test',op_id:randomUUID(),schema_version:1,kind,id:randomUUID(),base_revision:kind==='create'?0:1,created_at:new Date(now).toISOString(),expires_at:new Date(now+DOMAIN_POLICY.intentTtl).toISOString(),actor:'agent_inferred',...(kind==='create'?{data:{title:randomUUID(),note:null,status:'open',links:[]},provenance:{source:'fixture',source_refs:[],import_batch_id:null}}:{}),...overrides};if(['user_direct','user_via_agent'].includes(op.actor)&&!Object.hasOwn(overrides,'authorization_ref'))op.authorization_ref='bound:'+op.op_id;return op;};
 t.after(()=>{db.close();if(dir)rmSync(dir,{recursive:true,force:true});});
 return {get db(){return db;},get s(){return store;},a,u,principal,intent,tick(ms){now+=ms;},submit(op,p=a.p){return store.submit(p,'example',op);},make(data={},actor='agent_inferred'){const op=intent('create',{data:{title:randomUUID(),note:null,status:'open',links:[],...data},actor});const result=store.submit(actor==='agent_inferred'?a.p:u.p,'example',op);assert.equal(result.status,201,JSON.stringify(result));return {op,r:result.body.record,result};},get(id,p=a.p){return store.getRecord(p,'example',id,'core-test');},snapshot(p=a.p,query={}){return store.snapshot(p,'example',{core_instance_id:'core-test',...query});},counts(){return ['domain_records','domain_receipts','domain_changes'].map(table=>db.prepare(`SELECT COUNT(*) n FROM ${table}`).get().n);},reopen(){db.close();db=new DatabaseSync(name);store=new DomainStore(db,options);}};
}
const reason=r=>r.body.error?.code??r.body.reason;
const patch=(f,id,base,data,actor='agent_inferred')=>f.intent('patch',{id,base_revision:base,patch:data,actor});
const user=(f,kind,id,base,extra={})=>f.intent(kind,{id,base_revision:base,actor:'user_direct',...extra});

test('A01 current and disjoint concurrent patches preserve both fields; future base rejects',t=>{const f=fixture(t),{r}=f.make();assert.equal(f.submit(patch(f,r.id,1,{title:'changed'})).status,201);assert.equal(f.submit(patch(f,r.id,1,{note:'independent'})).status,201);assert.equal(f.get(r.id).body.record.revision,3);assert.equal(f.get(r.id).body.record.data.title,'changed');assert.equal(reason(f.submit(patch(f,r.id,9,{note:'future'}))),'invalid_base');assert.equal(f.get(r.id).body.record.revision,3);});
test('A02 complete atomic field groups and strict scalar/enum/null validation',t=>{const f=fixture(t),{r}=f.make({amount:10,currency:'USD'});assert.equal(reason(f.submit(patch(f,r.id,1,{amount:20}))),'incomplete_field_group');assert.equal(f.submit(patch(f,r.id,1,{amount:20,currency:'EUR'})).status,201);assert.equal(reason(f.submit(patch(f,r.id,1,{amount:30,currency:'JPY'}))),'stale_base');for(const bad of [{title:null},{amount:'10',currency:'USD'},{status:'unknown'},{unknown:true}])assert.equal(reason(f.submit(patch(f,r.id,2,bad))),'invalid_request');assert.equal(f.get(r.id).body.record.data.currency,'EUR');});
test('A03/A04 actor conflict matrix and current-version user locks',t=>{const f=fixture(t),{r}=f.make();const imported=patch(f,r.id,1,{title:'imported'},'import');assert.equal(f.submit(imported).status,201);assert.equal(reason(f.submit(patch(f,r.id,1,{title:'ai'}))),'superseded');const confirmed=patch(f,r.id,1,{title:'user'},'user_direct');assert.equal(f.submit(confirmed,f.u.p).status,201);assert.equal(reason(f.submit(patch(f,r.id,3,{title:'latest AI'}))),'user_locked');assert.equal(reason(f.submit(patch(f,r.id,3,{title:'latest import'},'import'))),'user_locked');const before=f.counts();assert.equal(reason(f.submit(patch(f,r.id,2,{title:'another user'},'user_direct'),f.u.p)),'user_conflict');assert.deepEqual(f.counts(),before);assert.equal(f.get(r.id).body.record.data.title,'user');});
test('A04 authorization cannot be self-declared, forged or omitted',t=>{const f=fixture(t),{r}=f.make();for(const principal of [f.a.p,f.u.p]){const op=patch(f,r.id,1,{title:'forged'},'user_direct');op.authorization_ref='existing-message-id';assert.equal(reason(f.submit(op,principal)),'actor_not_authorized');}const g=fixture(t,{verification:false});const op=g.intent('create',{actor:'user_direct'});assert.equal(reason(g.submit(op,g.u.p)),'actor_not_authorized');assert.equal(g.db.prepare('SELECT COUNT(*) n FROM domain_ops').get().n,0);});
test('A05 multi-group rejection is atomic; same-value confirmation establishes user lock',t=>{const f=fixture(t),{r}=f.make();const confirm=patch(f,r.id,1,{title:r.data.title},'user_direct');confirm.confirm_fields=['title'];assert.equal(f.submit(confirm,f.u.p).status,201);assert.equal(reason(f.submit(patch(f,r.id,2,{title:'bad',note:'must not survive'}))),'user_locked');assert.equal(f.get(r.id).body.record.data.note,null);assert.equal(f.get(r.id).body.record.revision,2);assert.equal(reason(f.submit(patch(f,r.id,2,{note:null}))),'no_change');assert.equal(f.get(r.id).body.record.revision,2);});
test('A06 exact HMAC idempotency; changed request conflicts; no-op receipt stays original',t=>{const f=fixture(t),{op,r,result}=f.make();const before=f.counts();const replay=f.submit(op);assert.equal(replay.status,200);assert.equal(replay.body.receipt.receipt_id,result.body.receipt.receipt_id);assert.deepEqual(f.counts(),before);assert.equal(reason(f.submit({...op,data:{...op.data,title:'different'}})),'idempotency_conflict');assert.equal(reason(f.submit({...op,op_id:randomUUID()})),'id_exists');const raw=f.db.prepare('SELECT request_digest,result_json,op_meta_json FROM domain_ops WHERE op_id=?').get(op.op_id);assert.notEqual(raw.request_digest,createHash('sha256').update(canonicalJSON(op)).digest('hex'));assert.ok(!raw.result_json.includes(r.data.title));assert.ok(!raw.op_meta_json.includes(r.data.title));});
test('A07 persisted result survives reopen; cross principal, credential and binding denial',t=>{const f=fixture(t,{file:true}),{op,r}=f.make();f.reopen();assert.equal(f.s.getOperation(f.a.p,'example',op.op_id,'core-test').status,200);assert.equal(reason(f.s.getOperation(f.u.p,'example',op.op_id,'core-test')),'op_not_found');const rotated=f.s.rotatePrincipal(f.a.principal_id);assert.equal(f.s.authenticate(f.a.token),null);assert.equal(f.get(r.id).status,401);const p=f.s.authenticate(rotated.token);assert.equal(f.s.getOperation(p,'example',op.op_id,'core-test').status,200);assert.equal(f.get(r.id,{...p,installation_id:'another'}).status,401);f.s.revokePrincipal(p.principal_id);assert.equal(f.get(r.id,p).status,401);});
test('A08 stale user delete covers only provable uninterrupted AI patch history',t=>{for(const actor of ['agent_inferred','import','user_direct']){const f=fixture(t),{r}=f.make();assert.equal(f.submit(patch(f,r.id,1,{note:actor},actor),actor==='user_direct'?f.u.p:f.a.p).status,201);const deleted=f.submit(user(f,'delete',r.id,1),f.u.p);assert.equal(reason(deleted),actor==='agent_inferred'?null:'stale_delete');assert.equal(deleted.status,actor==='agent_inferred'?201:409);}const f=fixture(t),{r}=f.make();f.submit(patch(f,r.id,1,{note:'a'}));f.db.prepare("DELETE FROM domain_ops WHERE json_extract(op_meta_json,'$.kind')='patch'").run();assert.equal(reason(f.submit(user(f,'delete',r.id,1),f.u.p)),'stale_delete');});
test('A09 deleted replay never returns body, restore preserves identity and field lock',t=>{const f=fixture(t),{op,r}=f.make({title:'private body'},'user_direct');const del=user(f,'delete',r.id,1);assert.equal(f.submit(del,f.u.p).status,201);assert.equal(reason(f.submit(op,f.u.p)),'deleted_target');const queried=f.s.getOperation(f.u.p,'example',op.op_id,'core-test');assert.equal(queried.body.target_state,'deleted');assert.ok(!JSON.stringify(queried).includes('private body'));assert.equal(f.get(r.id).status,410);assert.equal(reason(f.submit(patch(f,r.id,2,{note:'resurrect'}))),'deleted_target');f.tick(29*86400000);const restored=f.submit(user(f,'restore',r.id,2),f.u.p);assert.equal(restored.status,201);assert.equal(restored.body.record.id,r.id);assert.equal(reason(f.submit(patch(f,r.id,3,{title:'ai'}))),'user_locked');});
test('A09/A10 restore boundary, immediate deletion, purge idempotency and immutable decisions',t=>{const f=fixture(t),{r}=f.make({title:'sensitive'});assert.equal(reason(f.submit(user(f,'purge',r.id,1),f.u.p)),'purge_target_alive');const del=user(f,'delete',r.id,1);assert.equal(f.submit(del,f.u.p).status,201);const original=f.db.prepare('SELECT result_json FROM domain_ops WHERE op_id=?').get(del.op_id).result_json;f.tick(30*86400000);assert.equal(reason(f.submit(user(f,'restore',r.id,2),f.u.p)),'restore_window_expired');assert.equal(f.s.runRetention().body.purged,1);assert.equal(f.s.runRetention().body.purged,0);assert.equal(f.get(r.id).body.tombstone.revision,3);assert.equal(f.db.prepare('SELECT result_json FROM domain_ops WHERE op_id=?').get(del.op_id).result_json,original);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_op_payloads').get().n,0);assert.equal(f.db.prepare('SELECT body_json FROM domain_records').get().body_json,null);assert.equal(reason(f.submit(user(f,'purge',r.id,3),f.u.p)),'already_purged');const g=fixture(t),created=g.make({title:'erase me'});g.submit(user(g,'delete',created.r.id,1,{permanent:true}),g.u.p);assert.equal(g.get(created.r.id).body.tombstone.body_state,'purged');assert.equal(g.db.prepare('SELECT COUNT(*) n FROM domain_op_payloads').get().n,0);});
test('A10 external purge requires both scopes and latest base; snapshots invalidate',t=>{const f=fixture(t),{r}=f.make();const snap=f.snapshot();f.submit(user(f,'delete',r.id,1),f.u.p);assert.equal(reason(f.snapshot(f.a.p,{snapshot_token:snap.body.snapshot_token})),'resync_required');const limited=f.principal('limited',{actors:['user_direct'],trusted_interactive:true,scopes:['example:purge']});assert.equal(reason(f.submit(user(f,'purge',r.id,2),limited.p)),'scope_forbidden');assert.equal(reason(f.submit(user(f,'purge',r.id,1),f.u.p)),'stale_base');assert.equal(f.submit(user(f,'purge',r.id,2),f.u.p).status,201);const before=f.counts();assert.equal(reason(f.submit(user(f,'purge',r.id,3),f.u.p)),'already_purged');assert.deepEqual(f.counts(),before);});
test('A11 authorized semantic dedup, user direct duplicate and invisible candidate isolation',t=>{const f=fixture(t),{r}=f.make({title:'repeat'});const duplicate=f.submit(f.intent('create',{data:{title:'repeat'}}));assert.equal(duplicate.status,200);assert.equal(duplicate.body.duplicate_of,r.id);const manual=f.submit(f.intent('create',{actor:'user_direct',data:{title:'repeat'}}),f.u.p);assert.equal(manual.status,201);assert.equal(manual.body.possible_duplicate,r.id);const restricted=f.principal('restricted',{origin_device_only:true});const unrelated=f.submit(f.intent('create',{data:{title:'repeat'}}),restricted.p);assert.equal(unrelated.status,201);assert.equal(unrelated.body.possible_duplicate,undefined);assert.equal(f.get(r.id,restricted.p).status,404);});
function mergeIntent(f,source,target,refs=[],data=target.data){return user(f,'merge',source.id,source.revision,{target_id:target.id,target_base_revision:target.revision,target_data:data,reference_updates:refs});}
test('A12 merge atomically binds complete source/target/reference write set',t=>{const f=fixture(t),source=f.make({title:'source'}).r,target=f.make({title:'target'}).r,ref=f.make({links:[source.id]}).r;const op=mergeIntent(f,source,target,[{id:ref.id,base_revision:1,patch:{links:[target.id]}}],{...target.data,title:'combined'});const result=f.submit(op,f.u.p);assert.equal(result.status,201,JSON.stringify(result));assert.deepEqual(new Set(result.body.receipt.targets.map(r=>r.id)),new Set([source.id,target.id,ref.id]));assert.equal(result.body.receipt.change_sequences.length,3);assert.equal(f.get(source.id).body.tombstone.merged_into,target.id);assert.deepEqual(f.get(ref.id).body.record.data.links,[target.id]);assert.equal(f.get(ref.id).body.record.revision,2);assert.equal(reason(f.submit(user(f,'restore',source.id,2),f.u.p)),'merge_restore_unsupported');});
test('A12 hidden, missing, stale and unrelated reference changes reject complete merge',t=>{for(const kind of ['missing','stale','unrelated','hidden']){const f=fixture(t),source=f.make().r,target=f.make().r,ref=f.make({links:[source.id]}).r;const refs=kind==='missing'?[]:[{id:ref.id,base_revision:kind==='stale'?0:1,patch:kind==='unrelated'?{links:[target.id],note:'unrelated'}:{links:[target.id]}}];const p=kind==='hidden'?f.principal('limited',{actors:['user_direct'],trusted_interactive:true,record_ids:[source.id,target.id]}).p:f.u.p;const before=f.counts();const result=f.submit(mergeIntent(f,source,target,refs),p);assert.equal(reason(result),'reference_conflict');assert.deepEqual(f.counts(),before);assert.equal(f.get(source.id).status,200);assert.deepEqual(f.get(ref.id).body.record.data.links,[source.id]);assert.ok(!JSON.stringify(result).includes(ref.id));}});
test('A13 status and processing acknowledgements cannot smuggle other fields',t=>{const f=fixture(t),{r}=f.make();const p=f.principal('planner',{processor:'planner',scopes:['example:status','example:ack','example:read']});assert.equal(reason(f.submit(f.intent('status',{id:r.id,base_revision:1,patch:{status:'done',title:'smuggled'}}),p.p)),'scope_forbidden');assert.equal(f.submit(f.intent('status',{id:r.id,base_revision:1,patch:{status:'done'}}),p.p).status,201);assert.equal(reason(f.submit(f.intent('ack_capture',{id:r.id,base_revision:2,processor:'organizer',disposition:{organizer:{done:true}}}),p.p)),'scope_forbidden');assert.equal(f.submit(f.intent('ack_capture',{id:r.id,base_revision:2,processor:'planner',disposition:{planner:{done:true}}}),p.p).status,201);const other=f.principal('organizer',{processor:'organizer'});assert.equal(f.submit(f.intent('ack_capture',{id:r.id,base_revision:2,processor:'organizer',disposition:{organizer:{done:true}}}),other.p).status,201);const current=f.get(r.id).body.record;assert.equal(current.data.title,r.data.title);assert.deepEqual(current.data.planner,{done:true});assert.deepEqual(current.data.organizer,{done:true});});
test('A14 empty object constraints, write-only callers, field permissions and generation change',t=>{const f=fixture(t),{r}=f.make();const denied=f.principal('none',{record_ids:[]});assert.equal(f.get(r.id,denied.p).status,404);const origins=f.principal('no-origin',{origins:[]});assert.equal(f.get(r.id,origins.p).status,404);const write=f.principal('write',{scopes:['example:create']});const result=f.submit(f.intent(),write.p);assert.equal(result.status,201);assert.equal(result.body.record,undefined);assert.equal(f.get(r.id,write.p).status,403);const restricted=f.principal('field',{fields:{example:['note']}});assert.equal(reason(f.submit(patch(f,r.id,1,{title:'denied'}),restricted.p)),'scope_forbidden');assert.equal(f.s.getRecord(f.a.p,'cycle',r.id,'core-test').status,404);assert.equal(f.s.getRecord(null,'example',r.id,'core-test').status,401);});
test('A15 off/shadow/frozen/authoritative namespaces and scope isolation',t=>{const f=fixture(t,{mode:'off'});const op=f.intent();assert.equal(reason(f.submit(op)),'domain_off');assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_ops').get().n,0);f.s.setMode('example','shadow');assert.equal(reason(f.submit(op)),'scope_forbidden');const shadow=f.principal('shadow',{scopes:['example:shadow_write','example:shadow_read']});const staged=f.submit(op,shadow.p);assert.equal(staged.status,202);assert.equal(staged.body.outcome,undefined);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_receipts').get().n,0);assert.equal(f.get(op.id).status,403);f.s.setMode('example','frozen');assert.equal(f.get(op.id,shadow.p).status,200);assert.equal(reason(f.submit(f.intent(),shadow.p)),'domain_frozen');assert.equal(f.s.getOperation(shadow.p,'example',op.op_id,'core-test').body.transport_state,'shadow_staged');f.s.setMode('example','authoritative');assert.equal(f.get(op.id).status,404);assert.equal(f.get(op.id,shadow.p).status,403);assert.equal(f.submit(op).status,201);});
test('A16 authenticated cursors bind principal/domain/install/generation/Core and watermark equality',t=>{const f=fixture(t);f.make();const snap=f.snapshot();const cursor=snap.body.manifest.base_cursor;assert.equal(f.s.changes(f.a.p,'example',{core_instance_id:'core-test',cursor}).status,200);for(const token of [undefined,cursor+'broken',cursor.replace(/.$/,'z')])assert.equal(reason(f.s.changes(f.a.p,'example',{core_instance_id:'core-test',cursor:token})),'resync_required');assert.equal(reason(f.s.changes(f.u.p,'example',{core_instance_id:'core-test',cursor})),'resync_required');assert.equal(reason(f.s.changes(f.a.p,'example',{core_instance_id:'wrong',cursor})),'core_identity_mismatch');const rotated=f.s.rotatePrincipal(f.a.principal_id);assert.equal(reason(f.s.changes(f.s.authenticate(rotated.token),'example',{core_instance_id:'core-test',cursor})),'resync_required');});
test('A17 state feed pagination returns latest records, tombstones and monotone issued-only ack',t=>{const f=fixture(t);const initial=f.snapshot().body.manifest.base_cursor;const records=Array.from({length:5},()=>f.make().r);f.submit(patch(f,records[0].id,1,{note:'latest'}));let cursor=initial,seen=[],hasMore=true;while(hasMore){const page=f.s.changes(f.a.p,'example',{core_instance_id:'core-test',cursor,limit:2});assert.equal(page.status,200);seen.push(...page.body.records);cursor=page.body.next_cursor;hasMore=page.body.has_more;}assert.equal(seen.length,5);assert.equal(seen.find(r=>r.id===records[0].id).data.note,'latest');const ack=c=>f.s.acknowledge(f.a.p,'example',{domain_protocol_version:1,core_instance_id:'core-test',cursor:c});assert.equal(ack(cursor).body.advanced,true);assert.equal(ack(initial).body.advanced,false);const forged=JSON.parse(Buffer.from(cursor.split('.')[0],'base64url'));forged.sequence+=1;const serialized=canonicalJSON(forged);const signed=Buffer.from(serialized).toString('base64url')+'.'+createHmac('sha256','synthetic-secret-only').update(serialized).digest('hex');assert.equal(reason(ack(signed)),'resync_required');assert.equal(reason(ack(6)),'resync_required');});
test('A18 snapshot fixed cut, complete digest, mutation isolation, expiry and deletion invalidation',t=>{const f=fixture(t);const original=Array.from({length:5},()=>f.make().r);let first=f.snapshot(f.a.p,{limit:2});assert.equal(first.body.has_more,true);assert.equal(first.body.manifest.base_cursor,null);const firstId=first.body.snapshot_id;f.submit(patch(f,original[4].id,1,{note:'after snapshot'}));let all=[...first.body.records];let page=first;while(page.body.has_more){page=f.snapshot(f.a.p,{snapshot_token:first.body.snapshot_token,page_token:page.body.next_page_token,limit:2});assert.equal(page.body.snapshot_id,firstId);all.push(...page.body.records);}assert.equal(all.length,5);assert.ok(all.every(r=>r.data.note===null));assert.equal(createHash('sha256').update(canonicalJSON(all)).digest('hex'),page.body.manifest.collection_digest);assert.ok(page.body.manifest.manifest_auth);f.tick(DOMAIN_POLICY.snapshotTtl);assert.equal(reason(f.snapshot(f.a.p,{snapshot_token:first.body.snapshot_token})),'resync_required');const next=f.snapshot(f.a.p,{limit:1});f.submit(user(f,'delete',original[0].id,1),f.u.p);assert.equal(reason(f.snapshot(f.a.p,{page_token:next.body.next_page_token})),'resync_required');});
test('A19 TTL boundary cannot reverse accepted result; future timestamps and request bounds',t=>{const f=fixture(t),{op}=f.make();const expired=f.intent();f.tick(DOMAIN_POLICY.intentTtl);assert.equal(f.submit(op).body.outcome,'duplicate');assert.equal(reason(f.submit(expired)),'intent_expired');assert.equal(f.s.getOperation(f.a.p,'example',expired.op_id,'core-test').body.result.outcome,'expired');const future=f.intent();future.created_at=new Date(start+DOMAIN_POLICY.intentTtl+DOMAIN_POLICY.futureSkew+1).toISOString();future.expires_at=new Date(Date.parse(future.created_at)+1000).toISOString();assert.equal(reason(f.submit(future)),'invalid_request');const huge=f.intent('create',{data:{title:'x'.repeat(DOMAIN_POLICY.maxOpBytes)}});assert.equal(reason(f.submit(huge)),'payload_too_large');assert.equal(reason(f.submit([f.intent()])),'batch_not_supported');assert.equal(reason(f.snapshot(f.a.p,{limit:501})),'invalid_request');assert.equal(DOMAIN_POLICY.outboxItems,5000);assert.equal(DOMAIN_POLICY.outboxBytes,50000000);assert.equal(DOMAIN_POLICY.reminderAge,7*86400000);});
test('A20 crash hooks roll back records, receipts, changes and result together; retry accepts once',t=>{for(const phase of ['after_preflight','after_records','after_result','before_commit']){const f=fixture(t),op=f.intent();const before=f.counts();f.s.fault=at=>{if(at===phase)throw new Error('synthetic crash');};assert.throws(()=>f.submit(op),/synthetic crash/);assert.deepEqual(f.counts(),before);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_ops').get().n,0);f.s.fault=null;assert.equal(f.submit(op).status,201);assert.equal(f.submit(op).body.outcome,'duplicate');assert.deepEqual(f.counts(),[1,1,1]);}});
test('A24 schema 5 fails closed without adding tables and example has no cross-domain power',t=>{const db=new DatabaseSync(':memory:');t.after(()=>db.close());db.exec("CREATE TABLE core_metadata(key TEXT,value TEXT);INSERT INTO core_metadata VALUES('schema_version','5');");assert.throws(()=>new DomainStore(db,{nodeId:'x',cursorSecret:'s'}),e=>e.code==='schema_not_ready');assert.equal(db.prepare("SELECT COUNT(*) n FROM sqlite_master WHERE name LIKE 'domain_%'").get().n,0);const f=fixture(t);assert.equal(reason(f.s.submit(f.a.p,'ledger',f.intent())),'not_found');});

test('A16 retention watermark below rejects, equal continues and post-pruning snapshots stay usable',t=>{const f=fixture(t);const empty=f.snapshot().body.manifest.base_cursor;f.make();const current=f.snapshot().body.manifest.base_cursor;f.tick(DOMAIN_POLICY.feedRetention+1);assert.equal(f.s.runRetention().status,200);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_changes').get().n,0);assert.equal(reason(f.s.changes(f.a.p,'example',{core_instance_id:'core-test',cursor:empty})),'resync_required');assert.equal(f.s.changes(f.a.p,'example',{core_instance_id:'core-test',cursor:current}).status,200);const snapshot=f.snapshot();assert.equal(snapshot.body.manifest.base_watermark,1);assert.equal(snapshot.body.manifest.cut_sequence,1);assert.equal(f.s.changes(f.a.p,'example',{core_instance_id:'core-test',cursor:snapshot.body.manifest.base_cursor}).status,200);});
test('A16 active slow consumers prevent ordinary retention until expiry',t=>{const f=fixture(t);const first=f.snapshot();f.s.acknowledge(f.a.p,'example',{domain_protocol_version:1,core_instance_id:'core-test',cursor:first.body.manifest.base_cursor,snapshot_id:first.body.snapshot_id});f.make();f.tick(DOMAIN_POLICY.feedRetention+1);f.s.runRetention();assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_changes').get().n,1);f.tick(DOMAIN_POLICY.activeConsumer-DOMAIN_POLICY.feedRetention);f.s.runRetention();assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_changes').get().n,0);});
test('A17 byte-bound pages return every large record without truncating data',t=>{const f=fixture(t);const initial=f.snapshot().body.manifest.base_cursor;for(let n=0;n<12;n++)f.make({title:'large-'+n,note:'x'.repeat(210000)});const first=f.s.changes(f.a.p,'example',{core_instance_id:'core-test',cursor:initial,limit:500});assert.equal(first.status,200);assert.equal(first.body.has_more,true);assert.ok(Buffer.byteLength(JSON.stringify(first.body))<DOMAIN_POLICY.maxResponseBytes);const second=f.s.changes(f.a.p,'example',{core_instance_id:'core-test',cursor:first.body.next_cursor,limit:500});assert.equal(first.body.records.length+second.body.records.length,12);assert.ok([...first.body.records,...second.body.records].every(r=>r.data.note.length===210000));const snap=f.snapshot(f.a.p,{limit:500});assert.equal(snap.body.has_more,true);assert.ok(Buffer.byteLength(JSON.stringify(snap.body))<DOMAIN_POLICY.maxResponseBytes);});
test('A18 snapshot quota rejects new before replacement and completion ack is idempotent',t=>{const f=fixture(t);f.make();const snapshots=Array.from({length:4},()=>f.snapshot());assert.equal(reason(f.snapshot()),'domain_capacity_exceeded');const first=snapshots[0];const ack={domain_protocol_version:1,core_instance_id:'core-test',cursor:first.body.manifest.base_cursor,snapshot_id:first.body.snapshot_id};assert.equal(f.s.acknowledge(f.a.p,'example',ack).status,200);assert.equal(f.s.acknowledge(f.a.p,'example',ack).body.advanced,false);assert.equal(f.snapshot().status,200);const incomplete=snapshots[1];const id=f.db.prepare('SELECT id FROM domain_records').get().id;f.submit(user(f,'delete',id,1),f.u.p);assert.equal(reason(f.s.acknowledge(f.a.p,'example',{...ack,cursor:incomplete.body.manifest.base_cursor,snapshot_id:incomplete.body.snapshot_id})),'resync_required');});
test('A20 after-commit lost response remains accepted across reopen with exactly one receipt',t=>{const f=fixture(t,{file:true}),op=f.intent();f.s.fault=phase=>{if(phase==='after_commit')throw new Error('synthetic lost response');};assert.throws(()=>f.submit(op),/synthetic lost response/);assert.deepEqual(f.counts(),[1,1,1]);f.reopen();const result=f.s.getOperation(f.a.p,'example',op.op_id,'core-test');assert.equal(result.body.result.outcome,'accepted');assert.equal(f.submit(op).body.outcome,'duplicate');assert.deepEqual(f.counts(),[1,1,1]);});
test('A24 backup roles and runtime authority mutation fail closed and latch through byte restoration',t=>{for(const field of ['schema_version','node_id','cursor_secret','database_role']){const f=fixture(t);f.db.prepare("INSERT OR REPLACE INTO core_metadata(key,value) VALUES('node_id','core-test'),('cursor_secret','synthetic-secret-only')").run();f.db.exec("CREATE TABLE activity_metadata(key TEXT PRIMARY KEY,value TEXT);INSERT INTO activity_metadata VALUES('database_role','live');");const options={nodeId:'core-test',cursorSecret:'synthetic-secret-only',clock:()=>start};const s=new DomainStore(f.db,options);const table=field==='database_role'?'activity_metadata':'core_metadata';const prior=f.db.prepare(`SELECT value FROM ${table} WHERE key=?`).get(field).value;f.db.prepare(`UPDATE ${table} SET value=? WHERE key=?`).run(field==='schema_version'?'5':field==='database_role'?'backup_read_only':'mutated',field);assert.throws(()=>s.authenticate(f.a.token),e=>e.status===503);f.db.prepare(`UPDATE ${table} SET value=? WHERE key=?`).run(prior,field);assert.equal(reason(s.submit(f.a.p,'example',f.intent())),'core_not_ready');assert.deepEqual(f.counts(),[0,0,0]);assert.ok(new DomainStore(f.db,options).authenticate(f.a.token));}const f=fixture(t);f.db.exec("CREATE TABLE activity_metadata(key TEXT PRIMARY KEY,value TEXT);INSERT INTO activity_metadata VALUES('database_role','backup_read_only');");assert.throws(()=>new DomainStore(f.db,{nodeId:'core-test',cursorSecret:'synthetic-secret-only'}),e=>e.code==='backup_activation_unsupported');});
test('strict unknown intent/kind fields and complete reference request participate in idempotency',t=>{const f=fixture(t),{r}=f.make();for(const extra of [{revision:10},{data:{title:'smuggled'}},{fencing_token:'not-supported'},{epoch:3}]){const out=f.submit({...patch(f,r.id,1,{note:'a'}),...extra});assert.equal(out.status,400);}const source=f.make().r,target=f.make().r,ref=f.make({links:[source.id]}).r;const op=mergeIntent(f,source,target,[{id:ref.id,base_revision:1,patch:{links:[target.id]}}]);assert.equal(f.submit(op,f.u.p).status,201);const changed={...op,reference_updates:[]};assert.equal(reason(f.submit(changed,f.u.p)),'idempotency_conflict');});
test('write-only deleted retry and revoked actor cannot disclose historical target/body',t=>{const f=fixture(t);const write=f.principal('write',{scopes:['example:create']});const op=f.intent();const created=f.submit(op,write.p);assert.equal(created.status,201);f.submit(user(f,'delete',op.id,1),f.u.p);const replay=f.submit(op,write.p);assert.equal(reason(replay),'deleted_target');assert.equal(replay.body.tombstone,undefined);const reissued=f.s.configurePrincipal({principal_id:'write',device_id:'device-write',installation_id:'install-write',scopes:['example:create'],actors:[]});assert.equal(reason(f.s.getOperation(f.s.authenticate(reissued.token),'example',op.op_id,'core-test')),'actor_not_authorized');});

test('A03 exhaustive three-level concurrent actor matrix has no partial or ghost acceptance',t=>{const ranks={agent_inferred:1,import:2,user_direct:3};for(const current of Object.keys(ranks))for(const incoming of Object.keys(ranks)){const f=fixture(t),{r}=f.make();const existing=patch(f,r.id,1,{title:'current'},current);assert.equal(f.submit(existing,current==='user_direct'?f.u.p:f.a.p).status,201);const before=f.counts();const next=f.submit(patch(f,r.id,1,{title:'incoming'},incoming),incoming==='user_direct'?f.u.p:f.a.p);const expected=current==='user_direct'&&incoming!=='user_direct'?'user_locked':current==='user_direct'&&incoming==='user_direct'?'user_conflict':ranks[incoming]>ranks[current]?null:ranks[incoming]<ranks[current]?'superseded':'stale_base';assert.equal(reason(next),expected,`${current} versus ${incoming}`);if(expected){assert.deepEqual(f.counts(),before);assert.equal(f.get(r.id).body.record.data.title,'current');}else assert.equal(f.get(r.id).body.record.data.title,'incoming');}});
test('A10 deleted conflict payload is scrubbed while terminal decisions remain immutable',t=>{const f=fixture(t),{r}=f.make();f.submit(patch(f,r.id,1,{title:'new'}));const rejected=patch(f,r.id,1,{title:'private rejected proposal'});assert.equal(reason(f.submit(rejected)),'stale_base');assert.ok(f.db.prepare('SELECT payload_json FROM domain_op_payloads WHERE op_id=?').get(rejected.op_id).payload_json.includes('private rejected proposal'));const before=f.db.prepare('SELECT result_json FROM domain_ops WHERE op_id=?').get(rejected.op_id).result_json;f.submit(user(f,'delete',r.id,2,{permanent:true}),f.u.p);assert.equal(f.db.prepare('SELECT payload_json FROM domain_op_payloads WHERE op_id=?').get(rejected.op_id),undefined);assert.equal(f.db.prepare('SELECT result_json FROM domain_ops WHERE op_id=?').get(rejected.op_id).result_json,before);assert.ok(!JSON.stringify(f.db.prepare('SELECT * FROM domain_ops').all()).includes('private rejected proposal'));});
test('A12 reference faults after tentative writes roll back every member of the merge',t=>{const f=fixture(t),source=f.make().r,target=f.make().r,ref=f.make({links:[source.id]}).r;const op=mergeIntent(f,source,target,[{id:ref.id,base_revision:1,patch:{links:[target.id]}}],{...target.data,title:'combined'});const before=f.counts();f.s.fault=phase=>{if(phase==='after_records')throw new Error('merge crash');};assert.throws(()=>f.submit(op,f.u.p),/merge crash/);f.s.fault=null;assert.deepEqual(f.counts(),before);assert.equal(f.get(source.id).status,200);assert.deepEqual(f.get(ref.id).body.record.data.links,[source.id]);assert.equal(f.get(target.id).body.record.data.title,target.data.title);assert.equal(f.submit(op,f.u.p).status,201);});
test('A14 read permissions narrowed across generation invalidate snapshot and change capability',t=>{const f=fixture(t),a=f.make().r,b=f.make().r;const old=f.snapshot();const config={principal_id:f.a.principal_id,device_id:f.a.p.device_id,installation_id:f.a.p.installation_id,scopes:['example:read'],actors:['agent_inferred'],record_ids:[a.id]};const newToken=f.s.configurePrincipal(config);const principal=f.s.authenticate(newToken.token);assert.equal(reason(f.snapshot(principal,{snapshot_token:old.body.snapshot_token})),'resync_required');assert.equal(reason(f.s.changes(principal,'example',{core_instance_id:'core-test',cursor:old.body.manifest.base_cursor})),'resync_required');const current=f.snapshot(principal);assert.deepEqual(current.body.records.map(r=>r.id),[a.id]);assert.equal(f.get(b.id,principal).status,404);});
test('A19 record envelope size and capacity failure leave no newly accepted effects',t=>{const f=fixture(t);const overhead=f.intent('create',{data:{title:'a'}});const empty={...overhead,data:{title:''}};const tooLargeRecord={...overhead,data:{title:'x'.repeat(DOMAIN_POLICY.maxOpBytes-Buffer.byteLength(JSON.stringify(empty)))}};assert.equal(Buffer.byteLength(JSON.stringify(tooLargeRecord)),DOMAIN_POLICY.maxOpBytes);assert.equal(reason(f.submit(tooLargeRecord)),'payload_too_large');assert.deepEqual(f.counts(),[0,0,0]);const op=f.intent();const original=f.s.checkCapacity.bind(f.s);f.s.checkCapacity=(ns,domain)=>original(ns,domain,DOMAIN_POLICY.bodyQuota);assert.equal(reason(f.submit(op)),'domain_capacity_exceeded');f.s.checkCapacity=original;assert.deepEqual(f.counts(),[0,0,0]);assert.equal(f.submit(op).status,201);});
test('terminal private payload retention has finite expiry without rewriting earlier decision',t=>{const f=fixture(t),{r}=f.make();f.submit(patch(f,r.id,1,{note:'new'}));const op=patch(f,r.id,1,{note:'private conflict'});f.submit(op);const prior=f.db.prepare('SELECT result_json FROM domain_ops WHERE op_id=?').get(op.op_id).result_json;f.tick(DOMAIN_POLICY.intentTtl+DOMAIN_POLICY.terminalRetention);f.s.runRetention();assert.equal(f.db.prepare('SELECT payload_json FROM domain_op_payloads WHERE op_id=?').get(op.op_id),undefined);assert.equal(f.db.prepare('SELECT result_json FROM domain_ops WHERE op_id=?').get(op.op_id).result_json,prior);assert.equal(f.s.getOperation(f.a.p,'example',op.op_id,'core-test').body.result.reason,'stale_base');});

test('A11 trusted semantic adapter supports normalization and rejects hidden/deleted targets',t=>{const f=fixture(t);f.s.dedupHooks={example:({data,candidates})=>candidates.find(c=>c.data.title.trim().toLowerCase()===data.title.trim().toLowerCase())?.id??null};const original=f.make({title:'  Synthetic Title  '}).r;const duplicate=f.submit(f.intent('create',{data:{title:'synthetic title'}}));assert.equal(duplicate.body.duplicate_of,original.id);const direct=f.submit(f.intent('create',{actor:'user_direct',data:{title:'SYNTHETIC TITLE'}}),f.u.p);assert.equal(direct.status,201);assert.equal(direct.body.possible_duplicate,original.id);const restricted=f.principal('restricted',{origin_device_only:true});let inspected;f.s.dedupHooks.example=({candidates})=>{inspected=candidates;return original.id;};const denied=f.submit(f.intent('create',{data:{title:'Synthetic Title'}}),restricted.p);assert.equal(reason(denied),'duplicate_restricted');assert.deepEqual(inspected,[]);assert.ok(!JSON.stringify(denied).includes(original.id));f.submit(user(f,'delete',original.id,1),f.u.p);const after=f.submit(f.intent('create',{data:{title:'Synthetic Title'}}));assert.equal(reason(after),'duplicate_restricted');assert.ok(inspected.every(r=>r.id!==original.id));});
test('A11 throwing and asynchronous dedup adapters fail closed without accepted side effects',t=>{for(const hook of [()=>{throw new Error('private hook detail');},()=>Promise.resolve(null),()=>({id:'invalid'})]){const f=fixture(t);f.s.dedupHooks={example:hook};const result=f.submit(f.intent());assert.ok([409,503].includes(result.status));assert.ok(!JSON.stringify(result).includes('private hook detail'));assert.deepEqual(f.counts(),[0,0,0]);}});

test('accepted supersession records only immutable field/op identities and honors current query permissions',t=>{const f=fixture(t),{r}=f.make();const first=patch(f,r.id,1,{title:'first private'});f.submit(first);const original=f.db.prepare('SELECT result_json,op_meta_json FROM domain_ops WHERE op_id=?').get(first.op_id);const second=patch(f,r.id,1,{title:'second private'},'user_direct');f.submit(second,f.u.p);const meta=JSON.parse(f.db.prepare('SELECT op_meta_json FROM domain_ops WHERE op_id=?').get(second.op_id).op_meta_json);assert.ok(meta.supersedes.some(x=>x.op_id===first.op_id&&x.group==='title'));assert.ok(!JSON.stringify(meta).includes('private'));assert.deepEqual(f.db.prepare('SELECT result_json,op_meta_json FROM domain_ops WHERE op_id=?').get(first.op_id),original);const credential=f.s.configurePrincipal({principal_id:'agent',device_id:'device-agent',installation_id:'install-agent',scopes:all.map(a=>'example:'+a),actors:['agent_inferred'],fields:{example:['note']}});assert.equal(reason(f.s.getOperation(f.s.authenticate(credential.token),'example',first.op_id,'core-test')),'scope_forbidden');});

test('domain receipts, feeds, snapshots and retention use independent namespace/domain sequences',t=>{const f=fixture(t,{file:true});f.s.registerDomain('other',schema,{mode:'authoritative'});const multi=f.principal('multi',{scopes:['example','other'].flatMap(d=>all.map(a=>d+':'+a))});const submit=(domain,op)=>f.s.submit(multi.p,domain,op);const snapshot=domain=>f.s.snapshot(multi.p,domain,{core_instance_id:'core-test'});const startExample=snapshot('example').body.manifest.base_cursor,startOther=snapshot('other').body.manifest.base_cursor;const e1=submit('example',f.intent()),o1=submit('other',f.intent()),e2=submit('example',f.intent()),o2=submit('other',f.intent());assert.deepEqual([e1,o1,e2,o2].map(r=>r.body.receipt.change_sequences),[[1],[1],[2],[2]]);for(const [domain,cursor] of [['example',startExample],['other',startOther]]){const page=f.s.changes(multi.p,domain,{core_instance_id:'core-test',cursor});assert.equal(page.body.records.length,2);assert.equal(f.s.unseal(page.body.next_cursor).sequence,2);assert.equal(snapshot(domain).body.manifest.cut_sequence,2);}f.s.setMode('example','shadow');const shadow=f.principal('shadow',{scopes:['example:shadow_read','example:shadow_write']});assert.equal(f.s.submit(shadow.p,'example',f.intent()).status,202);assert.equal(f.s.snapshot(shadow.p,'example',{core_instance_id:'core-test'}).body.manifest.cut_sequence,1);f.s.setMode('example','frozen');f.s.setMode('example','authoritative');f.tick(DOMAIN_POLICY.feedRetention+1);f.s.runRetention();assert.equal(f.db.prepare("SELECT COUNT(*) n FROM domain_changes WHERE namespace='production'").get().n,0);for(const domain of ['example','other']){const snap=snapshot(domain);assert.equal(snap.body.manifest.cut_sequence,2);assert.equal(snap.body.manifest.base_watermark,2);assert.equal(f.s.changes(multi.p,domain,{core_instance_id:'core-test',cursor:snap.body.manifest.base_cursor}).status,200);}f.reopen();assert.deepEqual(submit('example',f.intent()).body.receipt.change_sequences,[3]);assert.deepEqual(submit('other',f.intent()).body.receipt.change_sequences,[3]);const rows=f.db.prepare("SELECT sequence,domain,domain_sequence FROM domain_changes WHERE namespace='production' ORDER BY sequence").all();assert.equal(rows.length,2);assert.ok(rows[0].sequence>rows[0].domain_sequence);assert.deepEqual(rows.map(r=>r.domain_sequence),[3,3]);});
test('semantic duplicate payload follows its actual canonical target through permanent deletion',t=>{const f=fixture(t);const marker='DUPLICATE-REQUEST-SECRET-'+randomUUID();const original=f.make({title:'canonical synthetic'}).r;const duplicateOp=f.intent('create',{data:{title:'canonical synthetic',note:marker}});const duplicate=f.submit(duplicateOp);assert.equal(duplicate.body.duplicate_of,original.id);const meta=JSON.parse(f.db.prepare('SELECT op_meta_json FROM domain_ops WHERE op_id=?').get(duplicateOp.op_id).op_meta_json);assert.equal(meta.duplicate_target_id,original.id);assert.deepEqual(meta.targets,[{id:original.id,revision:1}]);assert.ok(f.db.prepare('SELECT payload_json FROM domain_op_payloads WHERE op_id=?').get(duplicateOp.op_id).payload_json.includes(marker));const independentMarker='MANUAL-INDEPENDENT-'+randomUUID();const manualOp=f.intent('create',{actor:'user_direct',data:{title:'canonical synthetic',note:independentMarker}});const manual=f.submit(manualOp,f.u.p);assert.equal(manual.status,201);assert.equal(manual.body.possible_duplicate,original.id);f.snapshot();assert.equal(f.submit(user(f,'delete',original.id,1,{permanent:true}),f.u.p).status,201);assert.equal(reason(f.submit(duplicateOp)),'deleted_target');const result=f.s.getOperation(f.a.p,'example',duplicateOp.op_id,'core-test');assert.equal(result.status,200);assert.equal(result.body.target_state,'deleted');assert.equal(result.body.result.outcome,'duplicate');assert.equal(result.body.result.duplicate_of,undefined);assert.ok(!JSON.stringify(result).includes(marker));assert.equal(f.db.prepare('SELECT payload_json FROM domain_op_payloads WHERE op_id=?').get(duplicateOp.op_id),undefined);const tables=f.db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name LIKE 'domain_%'").all();assert.equal(tables.length,12);for(const {name} of tables)assert.ok(!JSON.stringify(f.db.prepare(`SELECT * FROM ${name}`).all()).includes(marker),name+' retains duplicate body');assert.equal(f.get(manualOp.id).body.record.data.note,independentMarker);assert.ok(f.db.prepare('SELECT payload_json FROM domain_op_payloads WHERE op_id=?').get(manualOp.op_id).payload_json.includes(independentMarker));assert.equal(f.submit(manualOp,f.u.p).body.outcome,'duplicate');});
test('import operation lookup rechecks narrowed source grants even after its payload is purged',t=>{const f=fixture(t);const importer=f.principal('importer',{actors:['import'],import_sources:['sourceA']});const op=f.intent('create',{actor:'import',provenance:{source:'sourceA',source_refs:[],import_batch_id:'synthetic-batch'}});assert.equal(f.submit(op,importer.p).status,201);assert.equal(f.s.getOperation(importer.p,'example',op.op_id,'core-test').status,200);const rotated=f.s.configurePrincipal({principal_id:'importer',device_id:'device-importer',installation_id:'install-importer',scopes:all.map(a=>'example:'+a),actors:['import'],import_sources:['sourceB']});const restricted=f.s.authenticate(rotated.token);assert.equal(reason(f.s.getOperation(restricted,'example',op.op_id,'core-test')),'actor_not_authorized');assert.equal(f.submit(user(f,'delete',op.id,1,{permanent:true}),f.u.p).status,201);assert.equal(f.db.prepare('SELECT payload_json FROM domain_op_payloads WHERE op_id=?').get(op.op_id),undefined);assert.equal(reason(f.s.getOperation(restricted,'example',op.op_id,'core-test')),'actor_not_authorized');const restored=f.s.configurePrincipal({principal_id:'importer',device_id:'device-importer',installation_id:'install-importer',scopes:all.map(a=>'example:'+a),actors:['import'],import_sources:['sourceA']});assert.equal(f.s.getOperation(f.s.authenticate(restored.token),'example',op.op_id,'core-test').body.target_state,'deleted');});

test('first no-change and semantic duplicate cannot expose a prior merge receipt with hidden targets',t=>{const f=fixture(t);const source=f.make({title:'source'}).r,target=f.make({title:'target'}).r,reference=f.make({links:[source.id]}).r;const merge=mergeIntent(f,source,target,[{id:reference.id,base_revision:1,patch:{links:[target.id]}}],{...target.data,title:'merged'});assert.equal(f.submit(merge,f.u.p).status,201);const proposed=randomUUID();const limited=f.principal('limited',{actors:['user_direct','agent_inferred'],trusted_interactive:true,record_ids:[target.id,proposed]});const before=f.counts();const same=f.submit(patch(f,target.id,2,{title:'merged'},'user_direct'),limited.p);assert.equal(reason(same),'duplicate_restricted');assert.equal(same.body.outcome,'needs_resolution');assert.equal(same.body.receipt,null);const duplicate=f.submit(f.intent('create',{id:proposed,data:{title:'merged'}}),limited.p);assert.equal(reason(duplicate),'duplicate_restricted');assert.equal(duplicate.body.outcome,'needs_resolution');assert.equal(duplicate.body.receipt,null);assert.deepEqual(f.counts(),before);for(const result of [same,duplicate]){assert.ok(!JSON.stringify(result).includes(source.id));assert.ok(!JSON.stringify(result).includes(reference.id));}});
test('runtime issuance and completed snapshot caches are bounded without evicting a live unacked snapshot',t=>{const f=fixture(t);const unacked=f.snapshot();assert.equal(unacked.status,200);let completed=0,blocked=null;for(let n=0;n<DOMAIN_POLICY.runtimeConsumerEntries+2;n++){const snap=f.snapshot();if(snap.status!==200){blocked=snap;break;}const ack=f.s.acknowledge(f.a.p,'example',{domain_protocol_version:1,core_instance_id:'core-test',cursor:snap.body.manifest.base_cursor,snapshot_id:snap.body.snapshot_id});assert.equal(ack.status,200);completed++;}assert.ok(completed>0&&completed<DOMAIN_POLICY.runtimeConsumerEntries);assert.equal(reason(blocked),'domain_capacity_exceeded');const d=f.s.domain('example');const key=f.s.consumerKey(f.a.p,'production');assert.ok(d.runtime.issued[key].length<=DOMAIN_POLICY.runtimeConsumerEntries);assert.ok(Object.values(d.runtime.completed_snapshots).length<=DOMAIN_POLICY.runtimeConsumerEntries);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_snapshots').get().n,1);assert.equal(f.snapshot(f.a.p,{snapshot_token:unacked.body.snapshot_token}).status,200);f.tick(DOMAIN_POLICY.activeConsumer+1);assert.equal(f.s.runRetention().status,200);const after=f.s.domain('example');assert.deepEqual(after.runtime.issued,{});assert.deepEqual(after.runtime.completed_snapshots,{});assert.equal(f.snapshot().status,200);});
test('runtime metadata has domain-wide entry/byte limits and is included in online body quota',t=>{const f=fixture(t);assert.throws(()=>f.s.checkCapacity('production','example',DOMAIN_POLICY.bodyQuota-1),e=>e.code==='domain_capacity_exceeded');const d=f.s.domain('example');for(let n=0;n<9;n++)d.runtime.issued['production:synthetic-'+n]=Array.from({length:1000},(_,i)=>({digest:'synthetic-'+i,sequence:i,at:new Date(start).toISOString()}));assert.throws(()=>f.s.saveRuntime(d),e=>e.code==='domain_capacity_exceeded');assert.deepEqual(f.s.domain('example').runtime.issued,{});const oversized=f.s.domain('example');oversized.runtime.padding='x'.repeat(DOMAIN_POLICY.runtimeBytes);assert.throws(()=>f.s.saveRuntime(oversized),e=>e.code==='domain_capacity_exceeded');assert.equal(f.s.domain('example').runtime.padding,undefined);});
test('shadow retention uses Core change timestamps with the same active consumer floor and no receipt',t=>{const f=fixture(t,{mode:'shadow'});const shadow=f.principal('shadow',{scopes:['example:shadow_read','example:shadow_write']});const empty=f.snapshot(shadow.p);f.s.acknowledge(shadow.p,'example',{domain_protocol_version:1,core_instance_id:'core-test',cursor:empty.body.manifest.base_cursor,snapshot_id:empty.body.snapshot_id});assert.equal(f.submit(f.intent(),shadow.p).status,202);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_receipts').get().n,0);f.tick(DOMAIN_POLICY.feedRetention+1);f.s.runRetention();assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_changes').get().n,1);f.tick(DOMAIN_POLICY.activeConsumer-DOMAIN_POLICY.feedRetention);f.s.runRetention();assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_changes').get().n,0);assert.equal(f.s.domain('example').runtime.watermarks.shadow,1);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_receipts').get().n,0);assert.equal(f.submit(f.intent(),shadow.p).status,202);assert.equal(f.snapshot(shadow.p).body.manifest.cut_sequence,2);});
test('missing durable Core identity or signing secret rejects both old instances and reconstruction',t=>{for(const field of ['node_id','cursor_secret']){const f=fixture(t);f.db.prepare('DELETE FROM core_metadata WHERE key=?').run(field);assert.equal(f.submit(f.intent()).status,503);assert.throws(()=>new DomainStore(f.db,{nodeId:'core-test',cursorSecret:'synthetic-secret-only'}),e=>e.code==='core_not_ready'&&e.status===503);assert.deepEqual(f.counts(),[0,0,0]);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM domain_ops').get().n,0);}});

test('consumer cache keys remain distinct for opaque identities containing delimiters',t=>{const f=fixture(t);const a=f.principal('a',{installation_id:'b:1:c'}),b=f.principal('a:1:b',{installation_id:'c'});assert.notEqual(f.s.consumerKey(a.p,'production'),f.s.consumerKey(b.p,'production'));const snapshot=f.snapshot(a.p);assert.equal(reason(f.s.acknowledge(b.p,'example',{domain_protocol_version:1,core_instance_id:'core-test',cursor:snapshot.body.manifest.base_cursor,snapshot_id:snapshot.body.snapshot_id})),'resync_required');});

test('historical merge lookup requires its full original scope and reference-field footprint',t=>{const f=fixture(t);const source=f.make({title:'source'}).r,target=f.submit(f.intent('create',{data:{title:'target',note:null,status:'open'}})).body.record,reference=f.make({links:[source.id]}).r;const op=mergeIntent(f,source,target,[{id:reference.id,base_revision:1,patch:{links:[target.id]}}],{...target.data,title:'merged'});assert.equal(f.submit(op,f.u.p).status,201);const meta=JSON.parse(f.db.prepare('SELECT op_meta_json FROM domain_ops WHERE op_id=?').get(op.op_id).op_meta_json);assert.deepEqual(meta.required_scopes,['read','patch','delete','merge']);assert.deepEqual(meta.target_fields.find(x=>x.id===reference.id).fields,['links']);assert.ok(!meta.fields.includes('links'));assert.ok(!meta.target_fields.find(x=>x.id===target.id).fields.includes('links'));assert.deepEqual(new Set(meta.target_fields.map(x=>x.id)),new Set([source.id,target.id,reference.id]));const rotate=config=>{const credential=f.s.configurePrincipal({principal_id:'user',device_id:'device-user',installation_id:'install-user',actors:['user_direct'],trusted_interactive:true,...config});return f.s.authenticate(credential.token);};const mergeOnly=rotate({scopes:['example:merge']});const deniedScopes=f.s.getOperation(mergeOnly,'example',op.op_id,'core-test');assert.equal(deniedScopes.status,403);assert.equal(reason(deniedScopes),'scope_forbidden');assert.equal(reason(f.submit(op,mergeOnly)),'scope_forbidden');for(const id of [source.id,target.id,reference.id])assert.ok(!JSON.stringify(deniedScopes).includes(id));const deniedReference=rotate({scopes:all.map(action=>'example:'+action),fields:{example:Object.keys(schema.fields).filter(field=>field!=='links')}});const deniedFields=f.s.getOperation(deniedReference,'example',op.op_id,'core-test');assert.equal(deniedFields.status,403);assert.equal(reason(deniedFields),'scope_forbidden');assert.equal(reason(f.submit(op,deniedReference)),'scope_forbidden');for(const id of [source.id,target.id,reference.id])assert.ok(!JSON.stringify(deniedFields).includes(id));const allowed=rotate({scopes:all.map(action=>'example:'+action),fields:{example:Object.keys(schema.fields)}});assert.equal(f.s.getOperation(allowed,'example',op.op_id,'core-test').status,200);});
test('historical purge lookup still requires delete scope after credential rotation',t=>{const f=fixture(t),{r}=f.make();assert.equal(f.submit(user(f,'delete',r.id,1),f.u.p).status,201);const purge=user(f,'purge',r.id,2);assert.equal(f.submit(purge,f.u.p).status,201);const meta=JSON.parse(f.db.prepare('SELECT op_meta_json FROM domain_ops WHERE op_id=?').get(purge.op_id).op_meta_json);assert.deepEqual(meta.required_scopes,['delete','purge']);const token=f.s.configurePrincipal({principal_id:'user',device_id:'device-user',installation_id:'install-user',actors:['user_direct'],trusted_interactive:true,scopes:['example:purge']});const principal=f.s.authenticate(token.token);const result=f.s.getOperation(principal,'example',purge.op_id,'core-test');assert.equal(reason(f.submit(purge,principal)),'scope_forbidden');assert.equal(result.status,403);assert.equal(reason(result),'scope_forbidden');assert.ok(!JSON.stringify(result).includes(r.id));assert.equal(result.body.receipt,undefined);});
